app_name = "auraos"
app_title = "AuraOS"
app_publisher = "Aura Productions"
app_description = (
    "Pipeline, pricing, quotes, jobs and money tracking "
    "for a small video production house"
)
app_email = "anhchung.work@gmail.com"
app_license = "unlicensed"

after_install = "auraos.setup.install.after_install"

# The frappe-ui SPA is served at /aura from auraos/www/aura.html
# (generated by `npm run build` in frontend/).
website_route_rules = [
    {"from_route": "/aura/<path:app_path>", "to_route": "aura"},
]
